26: export function createR2Storage(config: {
27:   accountId: string;
28:   bucketName: string;
29:   accessKeyId: string;
30:   secretAccessKey: string;
31:   publicUrl?: string;
32: }): StorageProvider {
33:   const s3 = new S3Client({
34:     region: "auto",
35:     endpoint: `https://${config.accountId}.r2.cloudflarestorage.com`,
36:     credentials: {
37:       accessKeyId: config.accessKeyId,
38:       secretAccessKey: config.secretAccessKey,
39:     },
40:   });
41: 
42:   return {
43:     async put(key: string, buffer: Buffer, mimeType: string) {
44:       await s3.send(
45:         new PutObjectCommand({
46:           Bucket: config.bucketName,
47:           Key: key,
48:           Body: buffer,
49:           ContentType: mimeType,
50:         }),
51:       );
52:       return this.getPublicUrl(key);
53:     },
54:     async get(key: string) {
55:       try {
56:         const res = await s3.send(new GetObjectCommand({ Bucket: config.bucketName, Key: key }));
57:         const byteArray = await res.Body?.transformToByteArray();
58:         if (!byteArray) return null;
59:         return { data: Buffer.from(byteArray), mimeType: res.ContentType ?? "application/octet-stream" };
60:       } catch {
61:         return null;
62:       }
63:     },
64:     async delete(key: string) {
65:       await s3.send(new DeleteObjectCommand({ Bucket: config.bucketName, Key: key }));
66:     },
67:     getPublicUrl(key: string) {
68:       if (config.publicUrl && config.publicUrl.trim()) {
69:         let pub = config.publicUrl.trim().replace(/\/$/, "");
70:         if (!pub.startsWith("http://") && !pub.startsWith("https://")) {
71:           pub = `https://${pub}`;
72:         }
73:         return `${pub}/${key}`;
74:       }
75:       return `https://${config.bucketName}.${config.accountId}.r2.cloudflarestorage.com/${key}`;
76:     },
77:   };
78: }
79: 
80: export function createLocalStorage(baseDir: string, publicBaseUrl?: string): StorageProvider {
81:   mkdirSync(baseDir, { recursive: true });
82: 
83:   return {
84:     async put(key: string, buffer: Buffer) {
85:       const filePath = join(baseDir, key);
86:       writeFileSync(filePath, buffer);
87:       return this.getPublicUrl(key);
88:     },
89:     async get(key: string) {
90:       const filePath = join(baseDir, key);
91:       if (!existsSync(filePath)) return null;
92:       const data = readFileSync(filePath);
93:       return { data, mimeType: "application/octet-stream" };
94:     },
95:     async delete(key: string) {
96:       const filePath = join(baseDir, key);
97:       if (existsSync(filePath)) unlinkSync(filePath);
98:     },
99:     getPublicUrl(key: string) {
100:       const base = publicBaseUrl ?? process.env.PUBLIC_BASE_URL ?? "";
101:       return `${base.replace(/\/$/, "")}/api/media/files/${key}`;
102:     },
103:   };
104: }
105: 
106: export function createStorageFromEnv(): StorageProvider {
107:   const accountId = process.env.R2_ACCOUNT_ID;
108:   const bucketName = process.env.R2_BUCKET_NAME;
109:   const accessKeyId = process.env.R2_ACCESS_KEY_ID;
110:   const secretAccessKey = process.env.R2_SECRET_ACCESS_KEY;
111:   const publicUrl = process.env.R2_PUBLIC_URL;
112: 
113:   if (accountId && bucketName && accessKeyId && secretAccessKey) {
114:     return createR2Storage({
115:       accountId,
116:       bucketName,
117:       accessKeyId,
118:       secretAccessKey,
119:       publicUrl,
120:     });
121:   }
122: 
123:   const localDir = process.env.MEDIA_DIR ?? join(process.cwd(), "data", "media");
124:   return createLocalStorage(localDir);
125: }
