127: export async function registerMediaRoutes(
128:   app: FastifyInstance,
129:   db: BetterSqlite3.Database,
130:   storage: StorageProvider = createStorageFromEnv(),
131: ) {
132:   await app.register(fastifyMultipart, {
133:     limits: {
134:       fileSize: 16 * 1024 * 1024, // 16 MB max for WhatsApp media
135:     },
136:   });
137: 
138:   // Local static file serving for local storage provider
139:   app.get<{ Params: { key: string } }>("/api/media/files/:key", async (request, reply) => {
140:     const item = await storage.get(request.params.key);
141:     if (!item) return reply.code(404).send({ error: "Media not found" });
142: 
143:     // Look up mime_type in database
144:     const row = db
145:       .prepare("SELECT mime_type FROM media_assets WHERE r2_key = ?")
146:       .get(request.params.key) as { mime_type: string } | undefined;
147: 
148:     reply.type(row?.mime_type ?? item.mimeType);
149:     return reply.send(item.data);
150:   });
151: 
152:   // Upload file endpoint
153:   app.post("/api/media/upload", async (request, reply) => {
154:     const data = await request.file();
155:     if (!data) return reply.code(400).send({ error: "No file uploaded" });
156: 
157:     const buffer = await data.toBuffer();
158:     const hash = createHash("sha256").update(buffer).digest("hex");
159:     const mimeType = data.mimetype;
160:     const filename = data.filename || `upload-${Date.now()}`;
161:     const ext = filename.includes(".") ? filename.split(".").pop() : "bin";
162:     const r2Key = `${hash.slice(0, 16)}-${Date.now()}.${ext}`;
163: 
164:     // Check if already stored with identical hash
165:     const existing = db
166:       .prepare("SELECT id, filename, mime_type AS mimeType, size, r2_key AS r2Key FROM media_assets WHERE hash = ?")
167:       .get(hash) as { id: number; filename: string; mimeType: string; size: number; r2Key: string } | undefined;
168: 
169:     if (existing) {
170:       return {
171:         id: existing.id,
172:         filename: existing.filename,
173:         mimeType: existing.mimeType,
174:         size: existing.size,
175:         publicUrl: storage.getPublicUrl(existing.r2Key),
176:       };
177:     }
178: 
179:     await storage.put(r2Key, buffer, mimeType);
180: 
181:     const info = db
182:       .prepare(`
183:         INSERT INTO media_assets (filename, mime_type, size, r2_key, hash)
184:         VALUES (?, ?, ?, ?, ?)
185:       `)
186:       .run(filename, mimeType, buffer.length, r2Key, hash);
187: 
188:     const id = Number(info.lastInsertRowid);
189:     const publicUrl = storage.getPublicUrl(r2Key);
190: 
191:     return reply.code(201).send({
192:       id,
193:       filename,
194:       mimeType,
195:       size: buffer.length,
196:       publicUrl,
197:     });
198:   });
199: 
200:   // List recent media assets
201:   app.get("/api/media", async () => {
202:     const rows = db
203:       .prepare(`
204:         SELECT id, filename, mime_type AS mimeType, size, r2_key AS r2Key, created_at AS createdAt
205:         FROM media_assets ORDER BY id DESC LIMIT 100
206:       `)
207:       .all() as Array<{ id: number; filename: string; mimeType: string; size: number; r2Key: string; createdAt: string }>;
208: 
209:     return rows.map((r) => ({
210:       ...r,
211:       publicUrl: storage.getPublicUrl(r.r2Key),
212:     }));
213:   });
214: 
215:   // Delete media asset
216:   app.delete<{ Params: { id: string } }>("/api/media/:id", async (request, reply) => {
217:     const id = Number(request.params.id);
218:     const row = db.prepare("SELECT id, r2_key AS r2Key FROM media_assets WHERE id = ?").get(id) as
219:       | { id: number; r2Key: string }
220:       | undefined;
221:     if (!row) return reply.code(404).send({ error: "not found" });
222: 
223:     try {
224:       await storage.delete(row.r2Key);
225:     } catch {}
226: 
227:     db.prepare("DELETE FROM media_assets WHERE id = ?").run(id);
228:     return { ok: true };
229:   });
230: }
