export async function generateAndUploadAllMedia(
  options: { storage?: StorageProvider; dbClient?: DbClient; localOutDir?: string } = {},
): Promise<UploadAllResults> {
  loadEnv();

  const storage = options.storage ?? createStorageFromEnv();
