      console.log(`🎬 Video (MP4): ${res.video.publicUrl} (${res.video.size} bytes, DB ID: ${res.video.dbId ?? "synced"})`);
      console.log("=======================================================\n");
      process.exit(0);
    })
    .catch((err) => {
      console.error("❌ Failed to generate and upload media:", err);
      process.exit(1);
    });
}

